P('\u77ed\u94fe\u63a5\u8fd9\u4e2a\u4e1c\u897f\u5927\u6982\u662f 2002 \u5e74\u5f00\u59cb\u7684\u3002\u90a3\u5e74\u6709\u4e2a\u4eba\u53eb Kevin Gilbertson\uff0c\u505a\u4e86\u4e00\u4e2a\u53eb TinyURL \u7684\u7f51\u7ad9\uff0c\u5e94\u8be5\u662f\u4e92\u8054\u7f51\u4e0a\u7b2c\u4e00\u4e2a\u88ab\u5e7f\u6cdb\u77e5\u9053\u7684\u77ed\u94fe\u63a5\u670d\u52a1\u3002\u5b83\u7684\u505a\u6cd5\u7279\u522b\u7b80\u5355\uff1a\u7528\u6237\u7ed9\u4e00\u4e2a\u957f URL\uff0c\u7cfb\u7edf\u8fd4\u56de\u4e00\u4e2a\u50cf "tinyurl.com/xxxxx" \u8fd9\u6837\u7684\u77ed\u94fe\u63a5\uff0c\u70b9\u51fb\u7684\u65f6\u5019\u505a 301 \u6c38\u4e45\u91cd\u5b9a\u5411\u3002\u8fd9\u79cd\u201c\u5b58\u50a8\u6620\u5c04\u7136\u540e\u91cd\u5b9a\u5411\u201d\u7684\u6a21\u5f0f\uff0c\u5230\u4eca\u5929\u4e5f\u662f\u6240\u6709\u77ed\u94fe\u63a5\u670d\u52a1\u7684\u57fa\u7840\u3002')

P('\u77ed\u94fe\u63a5\u771f\u6b63\u706b\u8d77\u6765\uff0c\u662f\u8ddf\u793e\u4ea4\u5a92\u4f53\u7684\u5174\u8d77\u6709\u5173\u7684\u30022006 \u5e74 Twitter \u4e0a\u7ebf\u540e\uff0c\u6bcf\u6761\u63a8\u6587\u53ea\u80fd\u53d1 140 \u4e2a\u5b57\u7b26\uff0c\u94fe\u63a5\u592a\u957f\u5c31\u4e0d\u591f\u7528\u4e86\u3002\u8fd9\u4e2a\u65f6\u5019 Bitly\uff08\u539f\u540d bit.ly\uff09\u5728 2008 \u5e74\u6210\u7acb\uff0c\u5f88\u5feb\u5c31\u505a\u5927\u4e86\u3002Bitly \u7684\u6210\u529f\u4e0d\u4ec5\u4ec5\u662f\u56e0\u4e3a\u80fd\u7f29\u77ed\u94fe\u63a5\uff0c\u66f4\u91cd\u8981\u7684\u662f\u5b83\u628a\u77ed\u94fe\u63a5\u53d8\u6210\u4e86\u4e00\u4e2a\u8425\u9500\u5206\u6790\u5de5\u5177\u2014\u2014\u80fd\u770b\u5230\u70b9\u51fb\u91cf\u3001\u6765\u6e90\u6e20\u9053\u3001\u5730\u7406\u4f4d\u7f6e\u7b49\u6570\u636e\u3002\u5230\u4e86 2011 \u5e74\uff0cBitly \u62ff\u5230\u4e86 1500 \u4e07\u7f8e\u5143\u7684\u878d\u8d44\uff0c\u4ece\u5de5\u5177\u578b\u4ea7\u54c1\u53d8\u6210\u4e86\u5e73\u53f0\u578b\u4ea7\u54c1\u3002')

P('\u5b66\u672f\u754c\u5bf9\u77ed\u94fe\u63a5\u7684\u5173\u6ce8\u4e5f\u662f\u540c\u4e00\u65f6\u671f\u5f00\u59cb\u7684\u3002Antoniades \u7b49\u4eba [1] \u5728 2011 \u5e74 WWW \u4f1a\u8bae\u4e0a\u53d1\u8868\u7684\u8bba\u6587\u201cwe.b: The Web of Short URLs\u201d\uff0c\u662f\u8fd9\u4e2a\u9886\u57df\u7684\u5f00\u5c71\u4e4b\u4f5c\u3002\u4ed6\u4eec\u505a\u4e86\u4e24\u4ef6\u4e8b\uff1a\u4e00\u662f\u5927\u89c4\u6a21\u722c\u53d6\u5404\u4e2a\u77ed\u94fe\u63a5\u670d\u52a1\uff0c\u4e8c\u662f\u722c\u53d6 Twitter \u6d88\u606f\u6d41\u3002\u7136\u540e\u7b2c\u4e00\u6b21\u7cfb\u7edf\u6027\u5730\u56de\u7b54\u4e86\u51e0\u4e2a\u95ee\u9898\uff1a\u77ed\u94fe\u63a5\u6307\u5411\u4ec0\u4e48\u5185\u5bb9\uff1f\u5b83\u4eec\u662f\u600e\u4e48\u88ab\u53d1\u5e03\u548c\u4f20\u64ad\u7684\uff1f\u6d3b\u8dc3\u65f6\u95f4\u6709\u591a\u4e45\uff1f\u4ed6\u4eec\u53d1\u73b0\u4e86\u51e0\u4e2a\u6709\u610f\u601d\u7684\u73b0\u8c61\uff1a\u77ed\u94fe\u63a5\u91cc\u70ed\u95e8\u7684\u7f51\u7ad9\u548c Alexa \u6392\u540d\u5dee\u5f88\u5927\uff1b\u70ed\u95e8\u7f51\u7ad9\u96c6\u5408\u6bd4\u8f83\u7a33\u5b9a\uff0c\u4f46\u5355\u4e2a\u77ed\u94fe\u63a5\u7684\u70ed\u5ea6\u7a97\u53e3\u671f\u5f88\u77ed\uff1b\u5927\u7ea6\u4e00\u534a\u7684\u77ed\u94fe\u63a5\u5728\u521b\u5efa\u4e09\u4e2a\u6708\u540e\u8fd8\u80fd\u7528\uff0c\u5e76\u4e0d\u662f\u4e00\u6b21\u6027\u7684\uff1b\u53e6\u5916\u77ed\u94fe\u63a5\u7684\u91cd\u5b9a\u5411\u8fc7\u7a0b\u4f1a\u5e26\u6765\u989d\u5916\u7684\u6027\u80fd\u5f00\u9500\u3002\u8fd9\u7bc7\u8bba\u6587\u88ab\u5f15\u7528\u4e86 148 \u6b21\u4ee5\u4e0a\uff0c\u540e\u9762\u5f88\u591a\u7814\u7a76\u90fd\u662f\u5728\u5b83\u7684\u57fa\u7840\u4e0a\u505a\u7684\u3002')

P('Maggi \u7b49\u4eba [3] \u5728 2013 \u5e74\u505a\u4e86\u4e00\u4e2a\u89c4\u6a21\u5f88\u5927\u7684\u6d4b\u91cf\u7814\u7a76\u3002\u4ed6\u4eec\u76d1\u6d4b\u4e86 622 \u4e2a\u77ed\u94fe\u63a5\u670d\u52a1\uff0c\u5728\u4e24\u5e74\u65f6\u95f4\u91cc\u6536\u96c6\u4e86\u5dee\u4e0d\u591a 2500 \u4e07\u6761\u77ed URL\u3002\u7ed3\u679c\u53d1\u73b0\uff0c\u867d\u7136\u6076\u610f\u77ed\u94fe\u63a5\u7684\u5360\u6bd4\u4e0d\u5927\uff0c\u4f46\u8d8b\u52bf\u662f\u4e0a\u5347\u7684\u3002\u66f4\u91cd\u8981\u7684\u662f\uff0c\u4ed6\u4eec\u53d1\u73b0\u90a3\u4e9b\u4e3b\u6d41\u77ed\u94fe\u63a5\u670d\u52a1\u7684\u53cd\u6ee5\u7528\u63aa\u65bd\u6548\u679c\u4e0d\u597d\uff0c\u5f88\u5bb9\u6613\u88ab\u7ed5\u8fc7\u3002\u8fd9\u7ed9\u4e86\u6211\u4e00\u4e2a\u5f88\u91cd\u8981\u7684\u63d0\u9192\uff1a\u77ed\u94fe\u63a5\u7cfb\u7edf\u7684\u5b89\u5168\u4e0d\u80fd\u53ea\u9760\u4e8b\u540e\u68c0\u6d4b\uff0c\u5f97\u4ece\u67b6\u6784\u5c42\u9762\u5c31\u8003\u8651\u3002')

P('Gupta \u7b49\u4eba [4] \u5728 2014 \u5e74\u7684 eCrime \u4f1a\u8bae\u4e0a\u53d1\u4e86\u4e00\u7bc7\u8bba\u6587\uff0c\u4e13\u95e8\u7814\u7a76\u4e86 Bitly \u7684\u5783\u573e\u94fe\u63a5\u68c0\u6d4b\u95ee\u9898\u3002\u4ed6\u4eec\u4ece Bitly \u62ff\u5230\u4e86\u5927\u7ea6 76 \u4e07\u6761\u88ab\u6807\u8bb0\u4e3a\u53ef\u7591\u7684\u77ed\u94fe\u63a5\u6570\u636e\uff0c\u53d1\u73b0 Bitly \u5141\u8bb8\u7528\u6237\u7f29\u77ed\u6076\u610f\u94fe\u63a5\uff0c\u800c\u4e14\u5728\u94fe\u63a5\u521b\u5efa\u65f6\u6ca1\u6709\u505a\u4efb\u4f55\u9884\u5148\u68c0\u67e5\u3002\u867d\u7136\u4e8b\u540e\u80fd\u53d1\u73b0\u4e00\u90e8\u5206\uff0c\u4f46\u4ece\u521b\u5efa\u5230\u88ab\u68c0\u6d4b\u4e4b\u95f4\u6709\u4e00\u6bb5\u65f6\u95f4\u5dee\u3002\u4ed6\u4eec\u63d0\u51fa\u7684\u534a\u76d1\u7763\u5206\u7c7b\u65b9\u6cd5\uff0c\u7ed9\u77ed\u94fe\u63a5\u5783\u573e\u68c0\u6d4b\u63d0\u4f9b\u4e86\u4e00\u4e2a\u53ef\u884c\u7684\u601d\u8def\u3002')

P('Le Page \u7b49\u4eba [5] \u5728 2018 \u5e74\u505a\u4e86\u4e00\u4e2a\u6709\u8da3\u7684\u5bf9\u6bd4\u7814\u7a76\u3002\u4ed6\u4eec\u7528\u77ed\u94fe\u63a5\u7684\u70b9\u51fb\u5206\u6790\u6570\u636e\uff0c\u6765\u6bd4\u8f83\u9493\u9c7c\u653b\u51fb\u548c\u6076\u610f\u8f6f\u4ef6\u653b\u51fb\u7684\u751f\u547d\u5468\u671f\u3002\u4ed6\u4eec\u53d1\u73b0\u9493\u9c7c\u653b\u51fb\u5728\u88ab\u4e3e\u62a5\u524d\u5927\u7ea6 4 \u5c0f\u65f6\u8fbe\u5230\u9ad8\u5cf0\uff0c\u70b9\u51fb\u7387\u9ad8\u4f46\u6d3b\u8dc3\u65f6\u95f4\u77ed\uff1b\u6076\u610f\u8f6f\u4ef6\u653b\u51fb\u5219\u63d0\u524d\u5927\u7ea6 4 \u5929\u5c31\u5f00\u59cb\u6d3b\u8dc3\uff0c\u70b9\u51fb\u7387\u4f4e\u4f46\u6301\u7eed\u65f6\u95f4\u5f88\u957f\u2014\u2014\u8d85\u8fc7\u4e00\u534a\u7684\u6076\u610f\u8f6f\u4ef6\u653b\u51fb\u6d3b\u8dc3\u4e86\u597d\u51e0\u5e74\u3002\u8fd9\u8bf4\u660e\u4e0d\u540c\u7c7b\u578b\u7684\u653b\u51fb\u9700\u8981\u4e0d\u540c\u7684\u5e94\u5bf9\u7b56\u7565\u3002')

