doc.add_heading('3.1.1  \u8868\u793a\u5c42', level=3)

P('\u8868\u793a\u5c42\u7531 17 \u4e2a Jinja2 \u6a21\u677f\u6587\u4ef6\u548c static/ \u76ee\u5f55\u4e0b\u7684\u9759\u6001\u8d44\u6e90\u7ec4\u6210\u3002\u6a21\u677f\u5f15\u64ce\u4f1a\u6839\u636e\u5f53\u524d\u8bf7\u6c42\u7684\u8bed\u8a00\u8bbe\u7f6e\uff08\u5b58\u5728 Flask \u7684 g \u5bf9\u8c61\u91cc\uff09\u6e32\u67d3\u5bf9\u5e94\u7684\u754c\u9762\u6587\u6848\u3002\u6211\u6ca1\u6709\u7528\u73b0\u5728\u6d41\u884c\u7684\u524d\u540e\u7aef\u5206\u79bb\u67b6\u6784\uff08\u6bd4\u5982 React/Vue + API\uff09\uff0c\u800c\u662f\u9009\u4e86\u670d\u52a1\u7aef\u6a21\u677f\u6e32\u67d3\u3002\u4e3b\u8981\u539f\u56e0\u6709\u4e09\u4e2a\uff1a\u7b2c\u4e00\uff0c\u77ed\u94fe\u63a5\u670d\u52a1\u7684\u5927\u591a\u6570\u9875\u9762\u90fd\u9700\u8981\u4ece\u670d\u52a1\u7aef\u62ff\u6570\u636e\uff0c\u670d\u52a1\u7aef\u6e32\u67d3\u7701\u6389\u4e86\u989d\u5916\u7684 API \u8bf7\u6c42\u3002\u7b2c\u4e8c\uff0cSEO \u5bf9\u77ed\u94fe\u63a5\u670d\u52a1\u6765\u8bf4\u4e0d\u662f\u91cd\u70b9\uff0cSPA \u65b9\u6848\u7684 SSR \u9700\u6c42\u5c31\u4e0d\u5b58\u5728\u4e86\u3002\u7b2c\u4e09\uff0c\u6a21\u677f\u6e32\u67d3\u65b9\u6848\u8ba9\u524d\u7aef\u590d\u6742\u5ea6\u964d\u4e86\u5f88\u591a\uff0c\u6211\u53ef\u4ee5\u628a\u7cbe\u529b\u653e\u5728\u4e1a\u52a1\u903b\u8f91\u4e0a\u3002')

P('CSS \u8fd9\u5757\uff0c\u6211\u642d\u5efa\u4e86\u4e00\u5957\u57fa\u4e8e Design Token \u7684\u8bbe\u8ba1\u7cfb\u7edf\u3002\u6240\u6709\u89c6\u89c9\u5c5e\u6027\u2014\u2014\u989c\u8272\u3001\u5b57\u53f7\u3001\u95f4\u8ddd\u3001\u5706\u89d2\u3001\u9634\u5f71\u3001\u52a8\u753b\u2014\u2014\u90fd\u901a\u8fc7 CSS \u53d8\u91cf\u5b9a\u4e49\u5728 :root \u91cc\uff0c\u5f62\u6210\u4e86\u4e00\u5957\u201c\u6696\u8272\u8c03\u7f16\u8f91\u98ce\u683c\u201d\u7684\u89c6\u89c9\u8bed\u8a00\u3002\u8fd9\u5957\u7cfb\u7edf\u8fd8\u539f\u751f\u652f\u6301\u6697\u8272\u6a21\u5f0f\uff0c\u901a\u8fc7\u5728 [data-theme="dark"] \u4e0b\u91cd\u5199\u53d8\u91cf\u5b9e\u73b0\uff0c\u5207\u6362\u65f6\u4e0d\u4f1a\u95ea\u70c1\u3002')

P('\u524d\u7aef JavaScript \u5168\u90e8\u7528\u539f\u751f\u5199\u7684\uff0c\u6ca1\u6709\u7528\u4efb\u4f55\u6846\u67b6\u3002\u56fe\u8868\u7528 Chart.js 4.4 \u6e32\u67d3\uff0c\u6a21\u6001\u6846\u3001Toast \u901a\u77e5\u3001\u8bed\u8a00\u5207\u6362\u3001\u6279\u91cf\u94fe\u63a5\u8bc6\u522b\u8fd9\u4e9b\u529f\u80fd\u90fd\u662f\u539f\u751f JS \u5b9e\u73b0\u7684\u3002\u8fd9\u6837\u505a\u7684\u597d\u5904\u662f\u9879\u76ee\u5f88\u8f7b\uff0c\u4e0d\u9700\u8981 npm/webpack \u6784\u5efa\u6d41\u7a0b\uff0c\u4ee3\u7801\u5199\u5b8c\u5c31\u80fd\u7528\u3002\u5bf9\u4e8e\u4e00\u4e2a\u4eba\u505a\u7684\u6bd5\u4e1a\u8bbe\u8ba1\u6765\u8bf4\uff0c\u8fd9\u4e2a\u9009\u62e9\u662f\u52a1\u5b9e\u7684\u3002')

