P('(1) URL \u7f29\u77ed\u4e0e\u77ed\u7801\u751f\u6210\u6a21\u5757\u3002\u5904\u7406 /shorten \u548c /batch_shorten \u4e24\u4e2a\u6838\u5fc3\u8def\u7531\uff0c\u8d1f\u8d23\u957f URL \u7684\u9a8c\u8bc1\u3001\u77ed\u7801\u751f\u6210\u4e0e\u51b2\u7a81\u68c0\u6d4b\u3001\u81ea\u5b9a\u4e49\u77ed\u7801\u7684\u683c\u5f0f\u6821\u9a8c\u4e0e\u4fdd\u7559\u5b57\u8fc7\u6ee4\u3001\u5230\u671f\u65f6\u95f4\u8ba1\u7b97\u3001\u6570\u636e\u5199\u5165\u6570\u636e\u5e93\u4ee5\u53ca\u4e8c\u7ef4\u7801\u751f\u6210\u3002\u8fd9\u4e2a\u6a21\u5757\u662f\u6574\u4e2a\u7cfb\u7edf\u6700\u590d\u6742\u7684\u5730\u65b9\uff0c\u6bcf\u4e00\u6b65\u90fd\u6709\u591a\u5c42\u6821\u9a8c\u3002')

P('(2) \u7528\u6237\u8ba4\u8bc1\u4e0e\u6388\u6743\u6a21\u5757\u3002\u5904\u7406\u6ce8\u518c\u3001\u767b\u5f55\u3001\u767b\u51fa\u548c\u5bc6\u7801\u91cd\u7f6e\u76f8\u5173\u7684\u8def\u7531\uff0c\u901a\u8fc7 @login_required \u81ea\u5b9a\u4e49\u88c5\u9970\u5668\u7edf\u4e00\u63a7\u5236\u8bbf\u95ee\u6743\u9650\u3002\u5bc6\u7801\u7528 Werkzeug \u5b89\u5168\u5e93\u505a\u52a0\u76d0\u54c8\u5e0c\uff0c\u5bc6\u7801\u91cd\u7f6e\u901a\u8fc7 UUID v4 \u4e00\u6b21\u6027\u4ee4\u724c\u5b9e\u73b0\u3002')

P('(3) \u94fe\u63a5\u7ba1\u7406\u6a21\u5757\u3002\u5904\u7406\u4eea\u8868\u76d8\u7684\u5206\u9875\u641c\u7d22\u4e0e\u8fc7\u6ee4\u5c55\u793a\u3001\u94fe\u63a5\u7f16\u8f91\u3001\u6807\u7b7e\u7ba1\u7406\u3001\u6709\u6548\u671f\u5ef6\u957f\u3001\u94fe\u63a5\u5220\u9664\u4ee5\u53ca\u5bc6\u7801\u67e5\u770b\u7b49\u64cd\u4f5c\u3002\u6240\u6709\u64cd\u4f5c\u6267\u884c\u524d\u90fd\u4f1a\u6821\u9a8c\u7528\u6237\u662f\u4e0d\u662f\u94fe\u63a5\u7684\u4e3b\u4eba\u6216\u8005\u7ba1\u7406\u5458\u3002')

P('(4) \u70b9\u51fb\u5206\u6790\u4e0e\u7edf\u8ba1\u6a21\u5757\u3002\u5904\u7406\u91cd\u5b9a\u5411\u548c\u7edf\u8ba1\u9875\u9762\uff0c\u5305\u542b\u5b9e\u65f6\u7684\u70b9\u51fb\u8bb0\u5f55\uff08IP\u3001User-Agent\u3001Referer\u3001\u5730\u7406\u4f4d\u7f6e\uff09\u3001\u70b9\u51fb\u8ba1\u6570\u66f4\u65b0\u3001\u4ee5\u53ca\u591a\u7ef4\u5ea6\u7684\u805a\u5408\u7edf\u8ba1\u5206\u6790\u3002')

P('(5) \u5b9a\u65f6\u4efb\u52a1\u6a21\u5757\u3002\u4e24\u4e2a Cron \u7aef\u70b9\uff0c\u4e00\u4e2a\u53d1\u5230\u671f\u63d0\u9192\u90ae\u4ef6\uff0c\u4e00\u4e2a\u6e05\u7406\u8fc7\u671f\u94fe\u63a5\uff0c\u7531\u5916\u90e8\u5b9a\u65f6\u4efb\u52a1\u8c03\u5ea6\u5668\u5b9a\u671f\u89e6\u53d1\u3002')

P('(6) \u7ba1\u7406\u9762\u677f\u6a21\u5757\u3002\u7ba1\u7406\u5458\u4e13\u5c5e\u7684 /admin \u8def\u7531\uff0c\u63d0\u4f9b\u7cfb\u7edf\u5168\u5c40\u6982\u89c8\u3001\u7528\u6237\u7ba1\u7406\u3001\u94fe\u63a5\u7ba1\u7406\u7b49\u89c6\u56fe\u3002')

doc.add_heading('3.1.3  \u6570\u636e\u6301\u4e45\u5c42', level=3)

P('LinkSnap \u901a\u8fc7\u4e00\u4e2a\u7edf\u4e00\u7684\u6570\u636e\u5e93\u8fde\u63a5\u5de5\u5382\u51fd\u6570 get_db_connection()\uff0c\u5b9e\u73b0\u4e86 SQLite \u548c PostgreSQL \u7684\u81ea\u52a8\u5207\u6362\u3002\u8fd9\u4e2a\u51fd\u6570\u68c0\u6d4b\u6709\u6ca1\u6709\u8bbe\u7f6e DATABASE_URL \u73af\u5883\u53d8\u91cf\uff0c\u6709\u5c31\u7528 PostgreSQL\uff0c\u6ca1\u6709\u5c31\u7528 SQLite\u3002\u5728 PostgreSQL \u6a21\u5f0f\u4e0b\u7528 DictCursor\uff0c\u8ba9\u67e5\u8be2\u7ed3\u679c\u7684\u8bbf\u95ee\u65b9\u5f0f\u548c SQLite \u7684 Row \u5de5\u5382\u4fdd\u6301\u4e00\u81f4\u3002\u4e0a\u5c42 Python \u4ee3\u7801\u4e0d\u7528\u7ba1\u5e95\u5c42\u662f\u54ea\u79cd\u6570\u636e\u5e93\uff0c\u5904\u7406\u65b9\u5f0f\u90fd\u4e00\u6837\u3002')

P('\u6570\u636e\u5e93\u521d\u59cb\u5316\u6a21\u5757 init_db() \u5728\u5e94\u7528\u542f\u52a8\u65f6\u81ea\u52a8\u6267\u884c\u3002\u5b83\u4f1a\u7528 CREATE TABLE IF NOT EXISTS \u6765\u786e\u4fdd\u8868\u7ed3\u6784\u5b58\u5728\uff0c\u7136\u540e\u901a\u8fc7\u4e00\u4e2a column_exists() \u8f85\u52a9\u51fd\u6570\u9010\u4e2a\u68c0\u67e5\u6bcf\u4e2a\u5b57\u6bb5\uff0c\u7f3a\u5c11\u7684\u5c31\u7528 ALTER TABLE ADD COLUMN \u8865\u4e0a\u3002\u8fd9\u79cd\u589e\u91cf\u5f0f\u8fc1\u79fb\u7684\u505a\u6cd5\uff0c\u8ba9\u65e7\u7248\u672c\u7684\u6570\u636e\u5e93\u6587\u4ef6\u5728\u5347\u7ea7\u540e\u8fd8\u80fd\u6b63\u5e38\u4f7f\u7528\uff0c\u4e0d\u7528\u641e Django/Alembic \u90a3\u5957\u590d\u6742\u7684\u8fc1\u79fb\u65b9\u6848\u3002')

