P('users \u8868\u5b58\u50a8\u7528\u6237\u8d26\u6237\u4fe1\u606f\u3002\u6838\u5fc3\u5b57\u6bb5\u5305\u62ec\uff1a\u81ea\u589e\u4e3b\u952e id\u3001\u552f\u4e00\u7ea6\u675f\u7684 username\uff08\u6700\u5927 100 \u5b57\u7b26\uff09\u3001\u552f\u4e00\u7ea6\u675f\u7684 email\uff08\u6700\u5927 255 \u5b57\u7b26\uff09\u3001\u52a0\u76d0\u54c8\u5e0c\u540e\u7684 password_hash\uff08255 \u5b57\u7b26\uff09\u3001\u6ce8\u518c\u65f6\u95f4 created_at\uff0c\u4ee5\u53ca\u5bc6\u7801\u91cd\u7f6e\u6240\u9700\u7684 reset_token\uff08UUID v4\uff09\u548c reset_token_expiry')
code(
    'CREATE TABLE users (\n'
    '    id SERIAL PRIMARY KEY,\n'
    '    username VARCHAR(100) NOT NULL UNIQUE,\n'
    '    email VARCHAR(255) NOT NULL UNIQUE,\n'
    '    password_hash VARCHAR(255) NOT NULL,\n'
    '    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n'
    '    reset_token VARCHAR(36),\n'
    '    reset_token_expiry TIMESTAMP\n'
    ');'
)

doc.add_heading('3.3.2  url_mappings \u8868', level=3)
P('url_mappings \u662f\u7cfb\u7edf\u7684\u6838\u5fc3\u4e1a\u52a1\u8868\uff0c\u5b58\u50a8\u6bcf\u6761\u77ed\u94fe\u63a5\u7684\u5b8c\u6574\u5143\u6570\u636e\u3002\u5b57\u6bb5\u8bbe\u8ba1\u6db5\u76d6\u4e86\u94fe\u63a5\u7ba1\u7406\u7684\u5168\u90e8\u9700\u6c42\u2014\u2014\u6807\u8bc6\u3001\u5185\u5bb9\uff08long_url \u7528 TEXT \u7c7b\u578b\u517c\u5bb9\u8d85\u957f URL\uff09\u3001\u5c5e\u6027\uff08is_custom \u533a\u5206\u7cfb\u7edf\u751f\u6210\u4e0e\u7528\u6237\u81ea\u5b9a\u4e49\uff09\u3001\u65f6\u95f4\uff08created_at\u3001updated_at\u3001expires_at\uff09\u3001\u8ba1\u6570\uff08click_count\uff09\u3001\u5f52\u5c5e\uff08user_id \u5916\u952e\u5173\u8054 users \u8868\uff09\u3001\u5b89\u5168\uff08password_hash \u5b58\u50a8\u8bbf\u95ee\u5bc6\u7801\u7684 Base64 \u7f16\u7801\uff09\u3001\u5206\u7c7b\uff08tag \u7528\u4e8e\u641c\u7d22\u8fc7\u6ee4\uff09\u548c\u8fd0\u7ef4\uff08reminder_sent \u6807\u8bb0\u662f\u5426\u5df2\u53d1\u9001\u5230\u671f\u63d0\u9192\u90ae\u4ef6\uff09\u3002')
code(
    'CREATE TABLE url_mappings (\n'
    '    id SERIAL PRIMARY KEY,\n'
    '    long_url TEXT NOT NULL,\n'
    '    short_code VARCHAR(50) NOT NULL UNIQUE,\n'
    '    is_custom BOOLEAN DEFAULT FALSE,\n'
    '    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n'
    '    click_count INTEGER DEFAULT 0,\n'
    '    user_id INTEGER REFERENCES users(id)\n'
    '        ON DELETE SET NULL,\n'
    '    expires_at TIMESTAMP,\n'
    '    password_hash VARCHAR(255),\n'
    '    tag VARCHAR(50),\n'
    '    updated_at TIMESTAMP,\n'
    '    reminder_sent INTEGER DEFAULT 0\n'
    ');'
)

doc.add_heading('3.3.3  clicks \u8868', level=3)
P('clicks \u8868\u4ee5 append-only \u65e5\u5fd7\u7684\u6a21\u5f0f\u8bb0\u5f55\u6bcf\u4e00\u6b21\u77ed\u94fe\u63a5\u8bbf\u95ee\u4e8b\u4ef6\u3002short_code \u5916\u952e\u5f15\u7528 url_mappings \u8868\uff0c\u8bbe\u7f6e\u4e86 ON DELETE CASCADE \u7b56\u7565\u2014\u2014\u94fe\u63a5\u88ab\u5220\u9664\u65f6\uff0c\u70b9\u51fb\u8bb0\u5f55\u81ea\u52a8\u6e05\u7406\u3002ip_address \u7528 VARCHAR(45) \u7c7b\u578b\u652f\u6301 IPv6 \u5730\u5740\u3002user_agent \u548c referer \u7528 TEXT \u7c7b\u578b\u3002\u5730\u7406\u4f4d\u7f6e\u76f8\u5173\u5b57\u6bb5\u5747\u4e3a\u53ef\u7a7a\uff0c\u517c\u5bb9 IP \u5730\u7406\u5b9a\u4f4d API \u67e5\u8be2\u5931\u8d25\u7684\u60c5\u51b5\u3002')
code(
    'CREATE TABLE clicks (\n'
    '    id SERIAL PRIMARY KEY,\n'
    '    short_code VARCHAR(50) NOT NULL\n'
    '        REFERENCES url_mappings(short_code)\n'
    '        ON DELETE CASCADE,\n'
    '    ip_address VARCHAR(45),\n'
    '    user_agent TEXT,\n'
    '    accessed_at TIMESTAMP DEFAULT\n'
    '        CURRENT_TIMESTAMP,\n'
    '    referer TEXT,\n'
    '    country VARCHAR(100),\n'
    '    region VARCHAR(100),\n'
    '    city VARCHAR(100)\n'
    ');'
)

doc.add_heading('3.4  \u4e09\u8bed\u56fd\u9645\u5316\u5f15\u64ce', level=2)

P('LinkSnap \u7684\u56fd\u9645\u5316\u5f15\u64ce\u662f\u7cfb\u7edf\u7684\u4e00\u4e2a\u4eae\u70b9\u3002\u5b83\u4f53\u73b0\u4e86\u9999\u6e2f\u4e2d\u82f1\u7ca4\u4e09\u8bed\u4ea4\u6c47\u7684\u8bed\u8a00\u6587\u5316\u7279\u8272\u3002\u8fd9\u4e2a\u5f15\u64ce\u901a\u8fc7\u72ec\u7acb\u7684 Python \u6a21\u5757 i18n.py \u5b9e\u73b0\uff0c\u548c Flask \u6846\u67b6\u6df1\u5ea6\u96c6\u6210\uff0c\u603b\u5171\u5927\u7ea6 140 \u884c\u4ee3\u7801\u5c31\u5b8c\u6210\u4e86\u5b8c\u6574\u7684\u7ffb\u8bd1\u52a0\u8f7d\u3001\u8bed\u8a00\u68c0\u6d4b\u3001\u683c\u5f0f\u5316\u8f93\u51fa\u548c\u8bed\u8a00\u5207\u6362\u529f\u80fd\u3002')

P('\u7ffb\u8bd1\u6570\u636e\u5b58\u5728 translations/ \u76ee\u5f55\u4e0b\u7684\u4e09\u4e2a JSON \u6587\u4ef6\u91cc\uff08en.json\u3001zh-CN.json\u3001zh-HK.json\uff09\uff0c\u6bcf\u4e2a\u6587\u4ef6\u5305\u542b 234 \u6761\u7ffb\u8bd1\u6761\u76ee\u3002\u6db5\u76d6\u4e86\u9875\u9762\u6807\u9898\u3001\u5bfc\u822a\u83dc\u5355\u3001\u8868\u5355\u6807\u7b7e\u3001\u529f\u80fd\u63cf\u8ff0\u3001\u6309\u94ae\u6587\u6848\u3001\u9519\u8bef\u63d0\u793a\u3001\u72b6\u6001\u6807\u7b7e\u7b49\u6240\u6709\u7528\u6237\u53ef\u89c1\u6587\u672c\u3002\u7ffb\u8bd1\u952e\u7528\u8bed\u4e49\u5316\u547d\u540d\uff0c\u6bd4\u5982 "shorten_btn"\u3001"password_incorrect"\uff0c\u770b\u4ee3\u7801\u7684\u65f6\u5019\u5c31\u80fd\u731c\u5230\u662f\u4ec0\u4e48\u610f\u601d\u3002\u7ffb\u8bd1\u6587\u4ef6\u5728\u6a21\u5757\u7ea7\u505a\u4e86\u5b57\u5178\u7f13\u5b58\uff0c\u907f\u514d\u6bcf\u6b21\u8bf7\u6c42\u90fd\u91cd\u65b0\u89e3\u6790 JSON\u3002')

P('\u8bed\u8a00\u68c0\u6d4b\u7528\u4e86\u56db\u5c42\u4f18\u5148\u7ea7\uff1a(1) URL \u67e5\u8be2\u53c2\u6570 ?lang=\uff0c\u9002\u5408\u5728\u5206\u4eab\u94fe\u63a5\u91cc\u9884\u8bbe\u8bed\u8a00\u3002(2) Flask Session \u91cc\u7684 locale \u952e\uff0c\u4fdd\u5b58\u5f53\u524d\u4f1a\u8bdd\u7684\u8bed\u8a00\u9009\u62e9\u3002(3) \u6d4f\u89c8\u5668 Cookie \u91cc\u7684 locale\uff08\u6709\u6548\u671f 365 \u5929\uff09\uff0c\u5b9e\u73b0\u8de8\u4f1a\u8bdd\u7684\u8bed\u8a00\u6301\u4e45\u5316\u3002(4) HTTP Accept-Language \u8bf7\u6c42\u5934\u901a\u8fc7 Flask \u5185\u7f6e\u7684 best_match() \u65b9\u6cd5\u4e0e\u7cfb\u7edf\u652f\u6301\u7684\u8bed\u8a00\u5217\u8868\u8fdb\u884c\u6700\u4f18\u5339\u914d\u3002\u56db\u5c42\u90fd\u6ca1\u5339\u914d\u5230\u5c31\u56de\u9000\u5230\u9ed8\u8ba4\u7684\u82f1\u6587\u3002')

P('\u7ffb\u8bd1\u51fd\u6570 _() \u652f\u6301 Python \u5b57\u7b26\u4e32\u683c\u5f0f\u5316\u53c2\u6570\uff0c\u6bd4\u5982 _("welcome_back", name=username) \u53ef\u4ee5\u5728\u7ffb\u8bd1\u6587\u672c\u91cc\u52a8\u6001\u63d2\u5165\u7528\u6237\u540d\u3002\u5982\u679c\u67d0\u4e2a\u7ffb\u8bd1\u952e\u5728\u7ffb\u8bd1\u6587\u4ef6\u91cc\u627e\u4e0d\u5230\uff0c\u51fd\u6570\u4f1a\u8fd4\u56de\u952e\u540d\u672c\u8eab\uff0c\u800c\u4e0d\u662f\u629b\u51fa\u5f02\u5e38\u6216\u8fd4\u56de\u7a7a\u5b57\u7b26\u4e32\uff0c\u8fd9\u6837\u9875\u9762\u4e0d\u4f1a\u56e0\u4e3a\u7f3a\u5c11\u7ffb\u8bd1\u800c\u5d29\u6e83\u3002')

doc.add_heading('3.5  \u5b89\u5168\u673a\u5236\u8bbe\u8ba1', level=2)

P('LinkSnap \u5728\u5b89\u5168\u8bbe\u8ba1\u4e0a\u56de\u5e94\u4e86\u5b66\u672f\u754c\u63ed\u793a\u7684\u77ed\u94fe\u63a5\u5b89\u5168\u5a01\u80c1 [2][4][7]\uff0c\u505a\u4e86\u4ece\u6570\u636e\u5c42\u5230\u5e94\u7528\u5c42\u7684\u591a\u5c42\u9632\u62a4\uff1a')

P('(1) SQL \u6ce8\u5165\u9632\u62a4\u3002\u6240\u6709\u6570\u636e\u5e93\u67e5\u8be2\u90fd\u7528\u53c2\u6570\u5316\u67e5\u8be2\uff0c\u7528 %s\uff08PostgreSQL\uff09\u6216 ?\uff08SQLite\uff09\u5360\u4f4d\u7b26\u4f20\u9012\u7528\u6237\u8f93\u5165\u3002Python \u4ee3\u7801\u91cc\u7edd\u4e0d\u51fa\u73b0\u5b57\u7b26\u4e32\u62fc\u63a5\u6784\u5efa SQL \u8bed\u53e5\u3002')

P('(2) \u5bc6\u7801\u5b89\u5168\u3002\u7528\u6237\u767b\u5f55\u5bc6\u7801\u7528 Werkzeug \u5b89\u5168\u54c8\u5e0c\uff08scrypt \u7b97\u6cd5\uff0c\u81ea\u52a8\u52a0\u76d0\uff09\u5b58\u50a8\u3002\u5bc6\u7801\u91cd\u7f6e\u4ee4\u724c\u7528 UUID v4 \u968f\u673a\u751f\u6210\uff0c\u6709 122 \u4f4d\u968f\u673a\u71b5\uff0c\u6709\u6548\u671f 1 \u5c0f\u65f6\u3002\u94fe\u63a5\u8bbf\u95ee\u5bc6\u7801\u76ee\u524d\u7528\u7684\u662f Base64 \u7f16\u7801\u5b58\u50a8\uff0c\u8fd9\u662f\u9879\u76ee\u5df2\u77e5\u7684\u6743\u8861\u2014\u2014\u56e0\u4e3a\u7528\u6237\u9700\u8981\u5728\u4eea\u8868\u76d8\u67e5\u770b\u81ea\u5df1\u8bbe\u7f6e\u7684\u5bc6\u7801\uff0c\u5b8c\u5168\u54c8\u5e0c\u5316\u4f1a\u8ba9\u8fd9\u4e2a\u529f\u80fd\u4e0d\u53ef\u7528\u3002\u4ee5\u540e\u53ef\u4ee5\u8003\u8651\u6362\u6210\u53ef\u9006\u5bf9\u79f0\u52a0\u5bc6\u3002')

P('(3) \u4f1a\u8bdd\u4e0e CSRF \u5b89\u5168\u3002Flask Session \u7528\u670d\u52a1\u7aef\u5bc6\u94a5\u7b7e\u540d\u7684\u5ba2\u6237\u7aef Cookie\uff0c\u5ba2\u6237\u7aef\u65e0\u6cd5\u7be1\u6539\u4f1a\u8bdd\u6570\u636e\u3002SECRET_KEY \u901a\u8fc7\u73af\u5883\u53d8\u91cf\u6ce8\u5165\u3002\u867d\u7136\u9879\u76ee\u76ee\u524d\u6ca1\u6709\u5b9e\u73b0 CSRF Token \u673a\u5236\uff0c\u4f46\u6240\u6709\u72b6\u6001\u53d8\u66f4\u64cd\u4f5c\u90fd\u9650\u5236\u4e3a POST \u8bf7\u6c42\uff0c\u5728\u4e00\u5b9a\u7a0b\u5ea6\u4e0a\u7f13\u89e3\u4e86 CSRF \u653b\u51fb\u9762\u3002')

P('(4) \u6743\u9650\u63a7\u5236\u3002@login_required \u88c5\u9970\u5668\u662f\u6240\u6709\u7ba1\u7406\u8def\u7531\u7684\u5b88\u95e8\u4eba\u3002\u94fe\u63a5\u7f16\u8f91\u3001\u5220\u9664\u3001\u7edf\u8ba1\u67e5\u8be2\u7b49\u64cd\u4f5c\u5728\u6267\u884c\u524d\u90fd\u6821\u9a8c\u7528\u6237\u8eab\u4efd\u3002\u7ba1\u7406\u5458\u8d26\u53f7\uff08username \u4e3a "admin"\uff09\u5177\u6709\u5168\u5c40\u67e5\u770b\u6743\u9650\u3002\u8de8\u7528\u6237\u8d8a\u6743\u64cd\u4f5c\u88ab\u62e6\u622a\u5e76\u8fd4\u56de HTTP 403 \u9519\u8bef\u3002')

P('(5) \u91cd\u5b9a\u5411\u5b89\u5168\u3002\u77ed\u94fe\u63a5\u91cd\u5b9a\u5411\u524d\u9a8c\u8bc1\u957f URL \u5fc5\u987b\u4ee5 http:// \u6216 https:// \u534f\u8bae\u5f00\u5934\uff0c\u62d2\u7edd javascript:\u3001data:\u3001file: \u7b49\u5176\u4ed6\u534f\u8bae\u3002\u8bed\u8a00\u5207\u6362\u7684\u91cd\u5b9a\u5411\u76ee\u6807\u4e5f\u9650\u5236\u4e3a\u4ec5\u5141\u8bb8\u76f8\u5bf9\u8def\u5f84\u3002')

P('(6) \u5b9a\u65f6\u4efb\u52a1\u7aef\u70b9\u4fdd\u62a4\u3002Cron \u7aef\u70b9\u901a\u8fc7 URL Token \u53c2\u6570\u8fdb\u884c\u7b80\u5355\u8ba4\u8bc1\uff0cToken \u503c\u901a\u8fc7\u73af\u5883\u53d8\u91cf\u914d\u7f6e\u3002\u867d\u7136\u5b89\u5168\u5f3a\u5ea6\u4e0d\u53ca\u57fa\u4e8e\u5bc6\u94a5\u7684\u7b7e\u540d\u65b9\u6848\uff0c\u4f46\u8db3\u4ee5\u9632\u6b62\u641c\u7d22\u5f15\u64ce\u722c\u866b\u548c\u968f\u673a\u626b\u63cf\u7684\u8bef\u89e6\u53d1\u3002')

